@Test
public void interceptorLogging() {
    final Logger logger = Logger.getLogger(BeansDeployer.class.getName());
    final Level originalLevel = logger.getLevel();
    logger.setLevel(FINE);
    final Collection<LogRecord> records = new ArrayList<>();
    final Handler testHandler = new Handler() {

        {
            setLevel(FINE);
        }

        @Override
        public void publish(final LogRecord record) {
            if (!record.getMessage().contains("Interceptor")) {
                return;
            }
            synchronized (records) {
                records.add(record);
            }
        }

        @Override
        public void flush() {
            // no-op
        }

        @Override
        public void close() throws SecurityException {
            // no-op
        }
    };
    logger.addHandler(testHandler);
    try {
        startContainer(singletonList(TransactionalInterceptor.class), singletonList(Thread.currentThread().getContextClassLoader().getResource(getClass().getName().replace('.', '/') + '/' + testName.getMethodName() + "/beans.xml").toExternalForm()));
    } finally {
        logger.removeHandler(testHandler);
        logger.setLevel(originalLevel);
    }
    assertTrue(records.size() >= 1);
    final LogRecord record = records.iterator().next();
    assertEquals(Level.FINE, record.getLevel());
    assertEquals("Interceptor class : " + TransactionalInterceptor.class.getName() + " is already defined with priority 1000", record.getMessage());
}

