    ObjectInputStream ois = new ObjectInputStream(bais);
    SessScopedBean ssb2 = (SessScopedBean) ois.readObject();
    Assert.assertNotNull(ssb2);
    Assert.assertNotNull(ssb2.getApp());
    Assert.assertTrue(ssb2.getApp().getI() == 4711);
